      "summary": "Santos의 긴 필드골이 목요일 접전을 갈랐다. Simmons와 Vera-Tucker의 IR 이동은 한 경기의 출전 문제를 넘어선 변화다. 나머지 리그에서는 새 부상과 거래 관심, 항소 결과를 확정 수준에 맞춰 읽는다."
